WITH parsed AS (SELECT id, plan, effective_from, currency, tier_limits, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, effective_from, entry_price, FIRST_VALUE(entry_price, TRUE) OVER (ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_entry_price, NTILE(4) OVER (PARTITION BY currency ORDER BY entry_price, id) AS entry_price_bucket, NTILE(3) OVER (PARTITION BY currency ORDER BY entry_price, id) AS entry_price_bucket_2 FROM parsed WHERE plan IN ('pro', 'enterprise');
